/**
 * What size to ask the model for, given the photograph going in.
 *
 * The try-on is a *comparison* before it is anything else: `<BeforeAfter>` wipes
 * between the photo and the preview, and `<PhotoFrame>` draws both halves with
 * `contentFit="cover"`. Cover crops whatever does not fit the frame, so two
 * images of different aspect are cropped by different amounts — the head lands
 * at a different scale and a different offset on each side of the wipe, and the
 * slider stops being a comparison of one face and becomes a comparison of two
 * framings. It reads as the generator having zoomed or shifted the photo, which
 * is not quite what happened: it returned the size it was asked for.
 *
 * So it is asked for the right one. `fitOutputSize` takes the photograph's own
 * pixel dimensions and returns the nearest size the model will accept that has
 * the same shape. Nothing about the crop is corrected after the fact and nothing
 * is said about it in the prompt — a prompt cannot set an output dimension, and
 * letterboxing the result to fit would be solving a framing problem by throwing
 * away pixels the user paid for.
 *
 * A note on where the constraints come from. They are gpt-image-2's, which is a
 * concrete model's rules living in a general-sounding module — the alternative
 * was `src/api/tryOn.ts`, which already carries a paragraph about every other
 * property of that request. This file exists separately because it has no
 * imports: that makes it loadable by `scripts/try-on.mjs` through
 * `lib/transpile.mjs`, so the terminal and the app compute the same size from
 * the same arithmetic rather than from two copies of it. Keep it import-free.
 */

export interface PixelSize {
  width: number;
  height: number;
}

/**
 * gpt-image-2's accepted sizes: "both dimensions as multiples of 16, max edge
 * 3840px, aspect ratio <= 3:1, total pixels between 655,360 and 8,294,400."
 *
 * `STEP` is the one that bites in practice and it is the reason this is a
 * function rather than a division. 1920×1080 — the size fal's own pricing table
 * names a bucket after — is not a legal size, because 1080 is not a multiple of
 * 16. Every edge here goes through `snap`.
 */
const STEP = 16;
const MAX_EDGE = 3840;
const MIN_PIXELS = 655_360;
const MAX_PIXELS = 8_294_400;
const MAX_ASPECT = 3;

/**
 * How many pixels to spend, independent of what shape they are in.
 *
 * 2,088,960 is 1920×1088 — the frame this app asked for when the size was fixed,
 * and therefore the pixel budget the current cost was measured against. Holding
 * the *area* constant and varying only the shape means matching the photograph
 * does not quietly change the bill: a portrait 1248×1664 and a landscape
 * 1920×1088 are the same number of pixels and the same price tier.
 *
 * Raising it is the lever for more strand detail, and it costs money — at
 * `quality: "medium"` gpt-image-2 is about $0.053 around here and about $0.068
 * at 2560×1440.
 */
export const TARGET_PIXELS = 2_088_960;

const clamp = (value: number, min: number, max: number): number =>
  Math.min(Math.max(value, min), max);

/** To the nearest legal edge: a multiple of 16, at least one step, at most 3840. */
const snap = (edge: number): number =>
  clamp(Math.round(edge / STEP) * STEP, STEP, MAX_EDGE);

/**
 * The photograph's shape at the model's pixel budget, or null if the photograph
 * could not be measured.
 *
 * Null is a real answer and the caller must handle it: measuring can fail on a
 * uri the platform will not decode, and the right response is to send no size at
 * all and let `image_size: "auto"` infer one, not to guess a shape.
 *
 * The aspect is clamped to 3:1 because the model will not go past it. A photo
 * more extreme than that comes back a different shape and the wipe misaligns —
 * unavoidable, and not worth failing a generation over.
 */
export function fitOutputSize(
  source: PixelSize | null | undefined,
  targetPixels: number = TARGET_PIXELS,
): PixelSize | null {
  if (!source) return null;
  const { width, height } = source;
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) return null;

  const aspect = clamp(width / height, 1 / MAX_ASPECT, MAX_ASPECT);
  // Snapping moves each edge by up to half a step, so a budget sitting exactly
  // on a limit can cross it once rounded. The margin is what keeps the arithmetic
  // below from needing to check.
  const budget = clamp(targetPixels, MIN_PIXELS * 1.05, MAX_PIXELS * 0.95);

  // w * h = budget, w / h = aspect.
  let w = Math.sqrt(budget * aspect);
  let h = w / aspect;

  // Only reachable at budgets far above the default; kept so the limit is
  // enforced here rather than by the API rejecting the request.
  const over = Math.max(w, h) / MAX_EDGE;
  if (over > 1) {
    w /= over;
    h /= over;
  }

  return { width: snap(w), height: snap(h) };
}
